49: class AppThemeData extends ThemeExtension<AppThemeData> {
50:   factory AppThemeData({required final Brightness brightness}) {
51:     final bool isDark = brightness == Brightness.dark;
52: 
53:     final ThemeColors themeColors = isDark ? ThemeColors.dark() : ThemeColors.light();
54:     final ThemeFonts themeFonts = ThemeFonts(color: isDark ? themeColors.white : themeColors.black);
55: 
56:     return AppThemeData.raw(brightness: brightness, themeFonts: themeFonts, themeColors: themeColors);
57:   }
58: 
59:   factory AppThemeData.light() => AppThemeData(brightness: Brightness.light);
60: 
61:   factory AppThemeData.dark() => AppThemeData(brightness: Brightness.dark);
62: 
63:   const AppThemeData.raw({required this.brightness, required this.themeFonts, required this.themeColors});
64: 
65:   final Brightness brightness;
66:   final ThemeFonts themeFonts;
67:   final ThemeColors themeColors;
68: 
69:   @override
70:   AppThemeData copyWith({
71:     final Brightness? brightness,
72:     final ThemeFonts? themeFonts,
73:     final ThemeColors? themeColors,
74:   }) {
75:     return AppThemeData.raw(
76:       brightness: brightness ?? this.brightness,
77:       themeFonts: themeFonts ?? this.themeFonts,
78:       themeColors: themeColors ?? this.themeColors,
79:     );
80:   }
81: 
82:   @override
83:   AppThemeData lerp(ThemeExtension<AppThemeData>? other, double t) {
